"""The attribution guard's hook routes: commands that skip or change the hooks git runs."""
import itertools
import re
from .shell import WRAPPERS, program, shape_of, text_of
from .files import (ENV_VALUE_OPTIONS, ENV_VALUE_SHORT, GIT_GLOBAL_FLAGS, GIT_VALUE_OPTIONS, abbreviates,
    git_subcommand, is_run_time_git, is_uncertain, takes_next_word)


LEFTHOOK_OFF_VALUES = {"0", "false"}
# Programs that run the command after their own words, and how many of those words are not
# options (`timeout 30 git`): the shell's wrappers and the common process runners.
RUNNERS = {**{name: 0 for name in WRAPPERS}, "timeout": 1, "chrt": 1, "taskset": 1, "stdbuf": 0,
           "setsid": 0, "ionice": 0, "noglob": 0, "strace": 0}
# Each word built at run time doubles the readings of one git call; past this many, it is refused.
MAX_RUN_TIME_WORDS = 10
# Subcommands whose --no-verify skips a hook, and the options of each that take a value, so a
# value (`-m -n`) is never read as an option. A long option may be shortened to any unique
# prefix of at least the length given.
NO_VERIFY_SUBCOMMANDS = {"commit", "am", "merge", "push", "rebase"}
SHORT_VALUES = {"commit": "cCFmt", "am": "C", "merge": "mFsX", "push": "o", "rebase": "sXx"}
# Letters whose value is optional and only ever written onto them (`-uno`, `-S<keyid>`).
ATTACHED_VALUES = {"commit": "uS", "am": "S", "merge": "S", "rebase": "S"}
LONG_VALUES = {
    "commit": {"--author", "--date", "--file", "--message", "--reedit-message", "--reuse-message",
               "--fixup", "--squash", "--template", "--trailer", "--cleanup", "--pathspec-from-file"},
    "am": {"--directory", "--exclude", "--include", "--patch-format", "--resolvemsg", "--whitespace"},
    "merge": {"--strategy", "--strategy-option", "--message", "--file", "--into-name", "--cleanup"},
    "push": {"--push-option", "--repo", "--receive-pack", "--exec"},
    "rebase": {"--strategy", "--strategy-option", "--exec", "--onto"},
}
# `git config`'s options that take the next word as their value, each with the shortest prefix git
# 2.56 reads as it (an ambiguous prefix makes git refuse the command).
CONFIG_VALUE_OPTIONS = {"--file": "--fil", "--blob": "--bl", "--type": "--t", "--default": "--d",
                        "--comment": "--co", "--value": "--v"}
CONFIG_VALUE_SHORT = {"-f", "-t"}
CONFIG_READS = {"get", "list", "edit", "get-regexp", "get-all", "get-urlmatch", "get-color",
                "get-colorbool"}
CONFIG_WRITES = {"set", "unset", "remove-section", "rename-section"}


def option_words(subcommand, rest):
    """The options of one git subcommand, one per letter of a bundle (`-nm` is `-n`, `-m`), with
    every option's value skipped, up to `--`."""
    options, skip, letters = [], False, SHORT_VALUES.get(subcommand, "")
    for word in (text_of(w) for w in rest):
        if skip:
            skip = False
        elif word == "--":
            break
        elif word.startswith("--"):
            options.append(word.split("=", 1)[0])
            skip = "=" not in word and any(abbreviates(word, o, o[:5]) for o in LONG_VALUES.get(subcommand, ()))
        elif word.startswith("-") and len(word) > 1:
            for k, letter in enumerate(word[1:], 1):
                options.append("-" + letter)
                if letter in letters:
                    skip = k == len(word) - 1 and not is_uncertain(word)
                    break
                if letter in ATTACHED_VALUES.get(subcommand, ""):  # `-uno`: the rest is its value
                    break
    return options


def names_hooks(setting):
    setting = setting.lower()
    return "hookspath" in setting or setting.startswith("hook.")


def names_hook_section(section):
    """Whether removing or renaming this section drops hook settings (`core` holds hooksPath)."""
    section = section.lower()
    return section in ("hook", "core") or section.startswith("hook.")


def config_option_takes_value(word):
    """Whether a `git config` option reads the next word as its value."""
    return takes_next_word(word, CONFIG_VALUE_SHORT, CONFIG_VALUE_OPTIONS)


def config_words(rest):
    """(the names and values `git config` reads, its options), or None when it is a read."""
    names, options, skip, ended = [], [], False, False
    for raw in rest:
        word = text_of(raw)
        # The old form (`git config <name> <value>`) stops reading options at the first name, so a
        # later `--get` is the value it stores.
        legacy = names and names[0] not in CONFIG_WRITES and names[0] not in CONFIG_READS
        if skip:
            skip = False
        elif word == "--" and not ended and not legacy:
            # Git reads every word after `--` as a name or value, never as an option.
            ended = True
        elif word.startswith("-") and not legacy and not ended:
            if word.startswith("--get") or word in ("-l", "--list"):
                return None
            options.append(word)
            skip = config_option_takes_value(word)
        else:
            names.append(word)
    return names, options


def config_sets_hooks(rest):
    """Whether `git config` sets or unsets a hook setting, or removes or renames a section that
    holds them; a read passes."""
    read = config_words(rest)
    if read is None:
        return False
    names, options = read
    unsets = any(abbreviates(o, "--unset-all", "--uns") for o in options)
    sections = any(abbreviates(o, "--remove-section", "--rem") or abbreviates(o, "--rename-section", "--ren")
                   for o in options)
    if names[:1] in (["remove-section"], ["rename-section"]):
        sections, names = True, names[1:]
    if sections:
        return bool(names) and names_hook_section(names[0])
    if names[:1] in (["set"], ["unset"]):
        unsets, names = unsets or names[0] == "unset", names[1:]
    elif names[:1] and names[0] in CONFIG_READS:
        return False
    return len(names) >= (1 if unsets else 2) and names_hooks(names[0])


def git_route(words):
    """The kind of route past the hooks one git call takes, or None. A word built at run time is
    read as its literal text with a NUL for each part built at run time (`--trailer=$WHO`,
    `"$S.hooksPath"`), and each one the parser says can expand to nothing is also read as no
    word, apart from the others (`git $OPTS commit`)."""
    head, rest = words[:1], words[1:]
    run_time = [i for i, word in enumerate(rest) if not isinstance(word, str) and word["canBeEmpty"]]
    if len(run_time) > MAX_RUN_TIME_WORDS:
        return "unread"
    known = [shape_of(word) for word in rest]
    for empty in itertools.product((False, True), repeat=len(run_time)):
        dropped = {i for i, is_empty in zip(run_time, empty) if is_empty}
        reading = [word for i, word in enumerate(known) if i not in dropped]
        route = literal_git_route(head + reading)
        if route:
            return route
    return None


def built_subcommand(words):
    """Whether git's subcommand comes from a word built at run time (`git "${args[@]}"`,
    `git "$@" -m x`), so that word may hold any subcommand and its options. A subcommand written
    right after the built words (`git $OPTS commit`) is read as usual; an option there may be one
    the built word's subcommand reads, so it names none. Options are read by their shape, as git
    receives them (`"-C$repo"` is `-C` with its value). A word before the subcommand place that
    may expand to several words (`git -C "$@"`) may fill that place too, so it counts as one,
    unless only git's own options stand between it and a subcommand written out
    (`git -C $repo -c x=y commit`): git reads those itself, so no subcommand's options are there."""
    i = git_subcommand([shape_of(word) for word in words])[0]
    is_written = i < len(words) and isinstance(words[i], str)
    places = [k for k in range(1, min(i, len(words)))
              if may_split(words[k]) and not (is_written and only_git_options(words[k + 1:i]))]
    if i < len(words) and not is_written:
        places.append(i)
    return any(names_no_subcommand_after(words, k) for k in places)


def only_git_options(words):
    """Whether these words are all git's own options with their values (`-c x=y`, `--no-pager`,
    `--git-dir=d`), which git reads before its subcommand. Words built at run time are left to
    their own check."""
    rest = iter(words)
    for word in rest:
        if not isinstance(word, str):
            continue
        if word in GIT_VALUE_OPTIONS:
            next(rest, None)
        elif word.split("=", 1)[0] not in GIT_GLOBAL_FLAGS | GIT_VALUE_OPTIONS:
            return False
    return True


def may_split(word):
    """Whether a word built at run time may expand to several words, with literal text or without
    (`"$@"`, `$X`, `--git-dir=$X`, `"--namespace=$@"`)."""
    return not isinstance(word, str) and bool(word["canBeMany"])


def names_no_subcommand_after(words, k):
    """Whether the first literal word after words[k] is missing or an option."""
    following = next((word for word in words[k + 1:] if isinstance(word, str)), None)
    return following is None or following.startswith("-")


def runs_program_at(words, i):
    """Whether words[i] may be the program the command runs, in any reading: itself, or one after
    RUNNERS (`sudo -u root`, `env A=1`, `timeout 30`), each read the same way. A word only named as
    an argument (`grep git "$f"`, `cp "$src/.git" "$dst"`, `command -v git`) is not, and neither
    is one behind a program outside RUNNERS. Every runner's readings move through the words
    together, in one pass from the left, so the work grows with the words however long the chain
    (`sudo -E sudo -E ...`): `states` holds each reading still alive, as the words its runner
    counts before its program (`timeout`'s duration) and whether the word before may have been an
    option that takes a value."""
    states = set()
    for k in range(i):
        states, may_start = next_states(words[k], states)
        name = program(words[k:k + 1]) if may_start or k == 0 else None
        if name in RUNNERS and not (name == "command" and only_looks_up(itertools.islice(words, k + 1, i))):
            states.add((RUNNERS[name], False))
    return i == 0 or bool(states)


def next_states(word, states):
    """(the readings alive after `word`, whether it may be a runner's program). A word right after
    an option, or after a word that may expand to several (`"${vars[@]}"`), may be the option's
    value, one of the counted words or the program, and a word built at run time from its first
    sign (`"$flag"`) may also be an option."""
    shape, following, may_start = shape_of(word), set(), False
    for others, after_option in states:
        if shape.startswith("-") or re.match(r"\w+=", shape):
            following.add((others, shape.startswith("-")))
        elif may_split(word):
            following.add((others, True))  # may hold options, their values, or nothing
        else:
            if shape.startswith("\0"):
                following.add((others, True))
            may_start = may_start or after_option or not others
            if after_option:
                following.add((others, False))
            if others:
                following.add((others - 1, False))
    return following, may_start


def only_looks_up(words):
    """Whether `command`'s own options (`-v`, `-pV`) make it print what a name is, not run it."""
    for word in words:
        shape = shape_of(word)
        if not shape.startswith("-") or shape.startswith("--"):
            return False
        if "v" in shape or "V" in shape:
            return True
    return False


def literal_git_route(words):
    """The route of a git call whose words after the program are all literal, or None."""
    i = git_subcommand(words)[0]
    before = words[1:i]
    settings = [v for k, v in zip(before, before[1:]) if k in ("-c", "--config-env")]
    settings += [w.split("=", 1)[1] for w in before if w.startswith("--config-env=")]
    if any(names_hooks(s) for s in settings):
        return "setting"
    if i >= len(words):
        return None
    subcommand, rest = words[i], words[i + 1:]
    if subcommand == "config":
        return "setting" if config_sets_hooks(rest) else None
    options = option_words(subcommand, rest)
    if subcommand in NO_VERIFY_SUBCOMMANDS and any(abbreviates(o, "--no-verify", "--no-v") for o in options):
        return "hooks"
    if subcommand in ("commit", "am") and "-n" in options:
        return "hooks"
    if subcommand != "commit":
        return None
    if any(abbreviates(o, "--trailer", "--tr") for o in options):
        return "trailer"
    reuses = ("--reuse-message", "--reedit-message")
    if any(o in ("-C", "-c") or any(abbreviates(o, r, r[:5]) for r in reuses) for o in options):
        return "reuse"
    return None


def env_assignments(words):
    """The `NAME=value` words an `env` in this command sets for the program it runs."""
    found = []
    for i in range(len(words)):
        if program(words[i:]) == "env":
            found += env_words(words[i + 1:])
    return found


def env_words(args):
    """The `NAME=value` words before `env`'s program. An option whose letters are built at run time
    (`-${Q}u`) may or may not take the next word, so every reading is followed at once: `states`
    holds, per reading still alive, whether the next word is an option's value."""
    found, states = [], {False}
    for word in args:
        shape, following = shape_of(word), set()
        for skip in states:
            if skip:
                following.add(False)
            elif shape.startswith("-"):
                following |= env_option_skips(shape)
            elif re.match(r"\w+=", shape):
                found.append(text_of(word))
                following.add(False)
        states = following
        if not states:
            break
    return found


def env_option_skips(word):
    """Whether an `env` option takes the next word, as the set of its possible answers."""
    unknown = next((i for i, sign in enumerate(word) if sign in "\0*?[{"), len(word))
    if unknown == len(word) or word.startswith("--") and "=" in word[:unknown]:
        return {takes_next_word(word, ENV_VALUE_SHORT, ENV_VALUE_OPTIONS)}
    return {False, True}


def turns_lefthook_off(commands, assignments):
    """Whether the command sets LEFTHOOK to 0 or false (by assignment, `export`, `env` or
    PowerShell's `$env:`), or to a value built at run time by any of them but `env`, or runs
    `lefthook uninstall`."""
    settings = [(s.get("name"), s.get("value")) for s in assignments if isinstance(s, dict)]
    settings += [tuple(text.split("=", 1)) for words in commands for text in env_assignments(words)]
    for name, value in settings:
        name = re.sub(r"^\$\{?(?:env:)?|\}$", "", str(name), flags=re.I).lower()
        if name == "lefthook" and (not isinstance(value, str) or value.strip("'\"").lower() in LEFTHOOK_OFF_VALUES):
            return True
    for words in commands:
        for i in range(len(words)):
            if program(words[i:]) == "lefthook":
                rest = [text_of(w) for w in words[i + 1:] if not text_of(w).startswith("-")]
                if rest[:1] == ["uninstall"]:
                    return True
    return False


def hook_route(groups, assignments, only_built=False):
    """The kind of route past git's hooks the commands of `with_nested`'s groups take, or None.
    A git run through a wrapper (`env A=1 git`, `sudo git`) counts, as does a word built at run
    time that names git (`$GIT`). With `only_built`, only a subcommand built at run time counts."""
    commands = [words for group, _, _ in groups for words in group]
    if not only_built and turns_lefthook_off(commands, assignments):
        return "lefthook"
    for words in commands:
        for i, word in enumerate(words):
            if program(words[i:]) == "git" or is_run_time_git(word):
                route = None if only_built else git_route(words[i:])
                if route:
                    return route
                if program(words[i:]) == "git" and runs_program_at(words, i) and built_subcommand(words[i:]):
                    return "built"
    return None

files..claude/hooks/no_ai_attribution/shell.py:
"""The attribution guard's shell reading: the parser in Bindwright's helper and the
command strings a nested shell runs."""
import json
import os
import re
import shutil
import subprocess
import time
from . import routes_in  # the hook file's own, set before this module loads


TEXT_TOOLS = {"awk", "gawk", "mawk", "grep", "egrep", "fgrep", "rg", "sed", "sort", "cut", "tr", "uniq",
              "head", "tail", "wc", "jq", "column", "paste", "join", "select-string", "sls", "findstr"}
PARSE_SECONDS = 6  # one parse
MAX_NESTED_SHELLS = 3  # `bash -c` inside `bash -c` ... read this many levels deep
POSIX_SHELLS = {"bash", "sh", "dash", "zsh", "ksh", "mksh", "ash"}
WRAPPERS = {"sudo", "doas", "env", "command", "builtin", "exec", "nohup", "nice", "time", "xargs"}
NO_NODE = ("this computer has no Node 18 or later, which the guard's parser needs to read the"
           " command. Install Node, then run /bindwright:update.")
NO_HELPER = "Bindwright's helper, which holds the guard's parser, is missing. Run /bindwright:update to install it."
OLD_HELPER = "Bindwright's helper is older than this guard. Run /bindwright:update to update it."
UNREAD = ("the guard's parser could not read this command (an array built at run time, PowerShell's"
          " `--%`, or syntax it rejects). Write it as plain commands.")
NESTED_UNREAD = ("a shell here runs a command string built at run time (`bash -c \"$CMD\"`), one nested more"
                 f" than {MAX_NESTED_SHELLS} deep, or one given to a nested PowerShell (`pwsh -Command`), which"
                 " the guard cannot read. Run the command directly.")
SLOW = (f"the guard's parser did not answer within {PARSE_SECONDS} s, so the command was not read."
        " Run it again once the computer is less busy.")
BROKEN = ("the guard's parser failed to run, so the command was not read. Run /bindwright:update to"
          " reinstall Bindwright's helper.")


def parser_script():
    """The shell parser in Bindwright's helper, which setup installs per computer with npm
    or pip; None when neither copy is there."""
    helper = os.path.join(os.path.expanduser("~"), ".bindwright", "helper")
    folders = [os.environ.get("BINDWRIGHT_HELPER")] if os.environ.get("BINDWRIGHT_HELPER") else [
        os.path.join(helper, "node_modules", "bindwright"), os.path.join(helper, "python", "bindwright")]
    scripts = [os.path.join(folder, "hooks", "shell-words.mjs") for folder in folders]
    return next((script for script in scripts if os.path.isfile(script)), None)


def node_program(cwd):
    """The `node` on PATH, or None when the only one is the session folder's own. On Windows a
    bare name is looked up in the current folder first, so a repo could ship its own
    `node.exe`: that search is switched off, and a match that is relative (a `.` on PATH) or
    sits in the session folder is refused."""
    os.environ["NoDefaultCurrentDirectoryInExePath"] = "1"
    found = shutil.which("node")
    if not found or not os.path.isabs(found):
        return None
    here = {os.path.normcase(os.path.realpath(folder)) for folder in (cwd, os.getcwd())}
    return None if os.path.normcase(os.path.realpath(os.path.dirname(found))) in here else found


def node_too_old(node, deadline):
    """Whether `node` is older than Node 18, which the parser needs; asked only once a run failed."""
    try:
        # Short, and never past the parses' deadline, so the hook answers before it is stopped.
        out = subprocess.run([node, "--version"], capture_output=True,
                             timeout=max(0.1, min(2, deadline - time.monotonic())))
    except (OSError, subprocess.TimeoutExpired):
        return False
    version = re.match(rb"\s*v(\d+)\.", out.stdout)
    return version is not None and int(version.group(1)) < 18


def parse(cmd, shell, cwd, deadline):
    """(each simple command's words, the variables the command sets, "") as the shell reads
    them (helper/hooks/shell-words.mjs); (None, None, why) when the parser is missing, older
    than this guard, fails, cannot read the command or has not answered by `deadline`."""
    node, script = node_program(cwd), parser_script()
    if not node:
        return None, None, NO_NODE
    if not script:
        return None, None, NO_HELPER
    if deadline <= time.monotonic():
        return None, None, SLOW
    try:
        # Bytes, not text: a text pipe on Windows would turn each LF into CR LF.
        out = subprocess.run([node, script, shell], input=cmd.encode("utf-8"),
                             capture_output=True, timeout=min(PARSE_SECONDS, deadline - time.monotonic()))
        data = json.loads(out.stdout.decode("utf-8")) if out.returncode == 0 else None
    except subprocess.TimeoutExpired:
        return None, None, SLOW
    except (OSError, ValueError):
        data = None
    if not isinstance(data, dict) or not isinstance(data.get("commands"), list):
        return None, None, NO_NODE if node_too_old(node, deadline) else BROKEN
    if not all(isinstance(command, list) for command in data["commands"]):
        return None, None, BROKEN
    words = [word for command in data["commands"] for word in command]
    if not all(isinstance(word, (str, dict)) for word in words):
        return None, None, BROKEN
    if not isinstance(data.get("assignments"), list) or any(
            isinstance(word, dict) and not {"shape", "canBeEmpty", "canBeMany"} <= word.keys() for word in words):
        return None, None, OLD_HELPER
    if any(isinstance(word, dict) and not is_word_list(word.get("braces", [])) for word in words):
        return None, None, BROKEN
    if data.get("error"):
        return None, None, UNREAD
    return with_brace_readings(data["commands"]), data["assignments"], ""


def is_word_list(value):
    """Whether a reply's word list is a JSON list of strings, the one shape the guard reads."""
    return isinstance(value, list) and all(isinstance(each, str) for each in value)


def with_brace_readings(commands):
    """Each command, then, when a word of it is a brace of plain text, the same command with that
    word as bash expands it (`{-F,msg.txt}` is `-F msg.txt`). Both are checked, since a shell that
    does not expand braces (dash, `set +B`) runs the first and bash runs the second."""
    read = []
    for words in commands:
        read.append(words)
        if any(isinstance(word, dict) and "braces" in word for word in words):
            read.append([each for word in words for each in (
                word["braces"] if isinstance(word, dict) and "braces" in word else [word])])
    return read


def with_nested(commands, assignments, shell, cwd, deadline, found, depth=1, around=()):
    """(groups, assignments, ""): a group (commands, the commands that place their folders, shell)
    for the parsed commands, then one per command string a shell in them may run, whose folder
    changes move only its own group; (None, None, why) when one cannot be read. Adds each to found."""
    placing = list(around) + list(commands)
    groups, assignments = [(commands, placing, shell)], list(assignments)
    for inner_shell, strings in filter(None, (shell_strings(w[i:], shell) for w in commands for i in shell_places(w))):
        for text in strings:
            found.append(text_of(text))
            if not isinstance(text, str) or depth > MAX_NESTED_SHELLS:
                return None, None, NESTED_UNREAD
            inner, inner_assignments, problem = parse(text, inner_shell, cwd, deadline)
            if not problem:
                inner_groups, inner_assignments, problem = with_nested(
                    inner, inner_assignments, inner_shell, cwd, deadline, found, depth + 1, placing)
            if problem:
                return None, None, problem
            groups, assignments = groups + inner_groups, assignments + inner_assignments
    return groups, assignments, ""


def shell_strings(words, caller):
    """(parser shell, the command strings it may run) for a shell program: each argument of a
    POSIX shell whose text names a route, a dict when built at run time. PowerShell joins its
    arguments into a script the guard does not rebuild, so a route they name is a dict; a script
    block after options alone (`pwsh -c { ... }`) is read by the outer parse; None otherwise."""
    name, args = program(words), words[1:]
    if name in POSIX_SHELLS:
        return "bash", [w for w in args if routes_in(text_of(w))[1] or routes_in(shape_of(w))[1]]
    if name not in ("pwsh", "powershell"):
        return None
    args = args[:script_file_at(name, args)]
    last = args[-1] if args and caller == "powershell" and not isinstance(args[-1], str) else ""
    options = all(re.fullmatch(r"-[A-Za-z]+", text_of(w)) for w in args[:-1])
    if options and text_of(last).lstrip().startswith("{"):
        args = args[:-1]
    joined = " ".join(text_of(w) for w in args)
    return "powershell", [{"dynamic": joined}] if routes_in(joined)[1] else []


def script_file_at(name, args):
    """Index of the .ps1 file a nested PowerShell runs past no-value switches, whose later words
    are its parameters; `powershell` reads a first plain word as a command, so it needs `-File`."""
    named = name == "pwsh"
    for i, w in enumerate(args):
        option = w.lstrip("-").lower() if isinstance(w, str) and w.startswith("-") else None
        if option not in ("noprofile", "nop", "nologo", "noninteractive", "noni", "file", "f"):
            is_script = isinstance(w, str) and w.lower().endswith(".ps1") and not routes_in(w)[1]
            return i if named and is_script else len(args)
        named = named or option in ("file", "f")
    return len(args)


def shell_places(words):
    """Words a shell may start at: those before a git, gh or text tool first or after a wrapper."""
    end = next((i for i in range(len(words)) if program(words[i:]) not in WRAPPERS), len(words))
    data = [i for i in range(end + 1) if program(words[i:]) in {"git", "gh"} | TEXT_TOOLS
            and "=" not in words[i]]
    return range(data[0] if data else len(words))


def text_of(word):
    """A word's literal value, or the source text of one the shell builds at run time."""
    return word if isinstance(word, str) else str(word.get("dynamic", ""))


def shape_of(word):
    """A word's literal value, or its text with a NUL for each part built at run time: what an
    option reader may trust, whichever way the source spells the expansion (`$Q`, `"$Q"`, `${Q}`)."""
    return word if isinstance(word, str) else str(word["shape"])


def program(words):
    if not words or not isinstance(words[0], str):
        return ""
    name = os.path.basename(words[0].replace("\\", "/")).lower()
    # Windows runs `git.exe`, `git.cmd` and `git.bat` alike when the command says `git`.
    return re.sub(r"\.(exe|cmd|bat|com)$", "", name)

files..claude/hooks/version-check.py:
r"""PreToolUse hook: check a release's version before it is tagged or proposed.

A release's size is easy to misjudge by hand: a new feature filed as a fix
ships as a patch. This hook reads every Bash and PowerShell command and, before
any of these runs, checks the version it names against the commits since the
last release with `.github/scripts/version_check.py`:

- `git tag <version>` (the version and an optional commit);
- `gh release create <version>`;
- `gh pr create` on a `release/<version>` branch, or with `--head` naming one.

The numbering comes from `advanced.versioning` in `.bindwright/project.json`:
`semver`, or `calver` with its `versionFormat`. With `none`, no saved answers
or no check script, every command runs. A tag that is not shaped like a version
of the scheme (`git tag backup`) is not a release, so it runs too.

A command whose text names a tag, a release or a PR is read the way the shell
reads it, by the shell parser in Bindwright's helper (`hooks/shell-words.mjs`),
so quoted text and here-documents are never taken for commands, and a git or gh
command behind a wrapper (`env`, `sudo`, `xargs`) is checked too. Options are
read as getopt reads them (`-am <message>`, `--head=<branch>`). `gh release
create` is measured at the version's tag when it exists, else at `--target`. A
version, commit or branch built at run time (`git tag $NEXT`, `--target=$BRANCH`) is out of
reach, so that release is not checked. The parser is a requirement, not an option: when it
cannot read the command (no helper or Node, a command it cannot parse, out of time), a command
that may make a release is blocked with what to install. The check refusing or failing to run
blocks the command with the reason.
"""

import json
import os
import re
import shutil
import subprocess
import sys
import time

SEMVER_TAG = re.compile(r"v?\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?")
CALVER_TAG = re.compile(r"v?\d+(?:\.\d+)*")
# The first pass over a command's text: it may match commands that make no release, never
# miss one that does; only a match is read by the shell parser.
MAY_BE_RELEASE = [[re.compile(word, re.IGNORECASE) for word in words]
                  for words in ([r"\bgit\b", r"\btag\b"], [r"\bgh\b", r"\b(?:release|pr)\b", r"\b(?:create|new)\b"])]


def may_be_release(command):
    """Whether the words of one MAY_BE_RELEASE list appear in order anywhere in the command. The
    earliest match of each word is enough, so it runs in linear time, where one pattern joining
    them with `.*` takes time that grows with the cube of a long command's length."""
    for words in MAY_BE_RELEASE:
        at = 0
        for word in words:
            hit = word.search(command, at)
            if not hit:
                break
            at = hit.end()
        else:
            return True
    return False
GH_CREATE = ("create", "new")
# The rest of an option word built at run time, and the key `read_options` records when a run-time
# word may be any option at all.
RUN_TIME_VALUE = "\0"
UNKNOWN_OPTION = "-\0"
RELEASE_BRANCH = re.compile(r"release/(.+)")

# Options that take a value, so it is never the version.
GIT_GLOBAL_VALUE = {"-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path",
                    "--config-env", "--attr-source", "--super-prefix"}
GH_GROUP_VALUE = {"-R", "--repo"}
TAG_VALUE = {"-m", "--message", "-F", "--file", "-u", "--local-user", "--cleanup",
             "--sort", "--format", "--contains", "--no-contains", "--merged", "--no-merged",
             "--points-at", "--trailer"}
# The modes that make no tag: git tag lists whenever it is given -n or a filter option.
TAG_NOT_CREATING = {"-d", "--delete", "-l", "--list", "-v", "--verify", "-n", "--contains",
                    "--no-contains", "--merged", "--no-merged", "--points-at"}
RELEASE_VALUE = {"-t", "--title", "-n", "--notes", "-F", "--notes-file", "--target", "-R",
                 "--repo", "--discussion-category", "--notes-start-tag"}
PR_VALUE = {"-t", "--title", "-b", "--body", "-F", "--body-file", "-B", "--base", "-R",
            "--repo", "-a", "--assignee", "-l", "--label", "-m", "--milestone", "-p",
            "--project", "-r", "--reviewer", "-T", "--template", "--recover", "-H", "--head"}
TEXT_TOOLS = {"echo", "printf", "write-output", "write-host", "awk", "gawk", "mawk", "grep", "egrep",
              "fgrep", "rg", "sed", "sort", "cut", "tr", "uniq", "head", "tail", "wc", "jq", "column",
              "paste", "join", "select-string", "sls", "findstr"}
# The hook's entry in .claude/settings.json stops it at 30 s; every step shares what is left of
# this budget, so the hook gives its own reason before that.
HOOK_SECONDS = 27
STARTED = time.monotonic()
PARSE_SECONDS = 6
OUT_OF_TIME = (f"the version check did not finish within {HOOK_SECONDS} s. Run the command again "
               "once the computer is less busy.")
UNREAD = ("Blocked: this command may make a release, and the version check could not read it. "
          "The check reads commands with the shell parser in Bindwright's helper, which needs "
          "Node 18 or later: install both with `/bindwright:setup`, or turn the check off with "
          "\"versioning\": \"none\" in .bindwright/project.json. With both installed, the parser "
          "could not read this command: run the release as a plain git tag, gh release create "
          "or gh pr create command of its own.")


def seconds_left():
    """What is left of the hook's time budget."""
    return max(0.0, STARTED + HOOK_SECONDS - time.monotonic())


def parser_script():
    """The helper's shell parser, or None when no copy is installed."""
    helper = os.path.join(os.path.expanduser("~"), ".bindwright", "helper")
    folders = [os.environ["BINDWRIGHT_HELPER"]] if os.environ.get("BINDWRIGHT_HELPER") else [
        os.path.join(helper, "node_modules", "bindwright"), os.path.join(helper, "python", "bindwright")]
    scripts = [os.path.join(folder, "hooks", "shell-words.mjs") for folder in folders]
    return next((script for script in scripts if os.path.isfile(script)), None)


def trusted_program(name, project):
    """The program on PATH as an absolute path, or None when the first one found is the project's.
    Windows looks a bare name up in the current folder first, so a repo could ship its own
    `git.exe` or `node.exe`: that search is switched off, and a relative match or one in the
    project or the current folder is refused."""
    os.environ["NoDefaultCurrentDirectoryInExePath"] = "1"
    found = shutil.which(name)
    if not found or not os.path.isabs(found):
        return None
    here = {os.path.normcase(os.path.realpath(folder)) for folder in (project, os.getcwd())}
    return None if os.path.normcase(os.path.realpath(os.path.dirname(found))) in here else found


def shell_commands(command, shell, project):
    """Each simple command's words as the shell reads them, or None when the parser cannot run
    or read the command. A word built at run time is a RunTime."""
    node, script = trusted_program("node", project), parser_script()
    if not node or not script:
        return None
    try:
        # Bytes, not text: a text pipe on Windows would turn each LF into CR LF.
        out = subprocess.run([node, script, shell], input=command.encode("utf-8"),
                             capture_output=True, timeout=min(PARSE_SECONDS, seconds_left()))
        data = json.loads(out.stdout.decode("utf-8")) if out.returncode == 0 else None
    except (OSError, subprocess.SubprocessError, ValueError):
        data = None
    if not isinstance(data, dict) or not isinstance(data.get("commands"), list) or data.get("error"):
        return None
    commands = data["commands"]
    # One entry of another shape makes the whole reply unread, never a command skipped.
    if not all(isinstance(words, list) and all(map(is_word, words)) for words in commands):
        return None
    return [[word if isinstance(word, str) else RunTime(word.get("prefix")) for word in words]
            for words in commands]


def is_word(word):
    """Whether the parser's word is text, or its marker for a word built at run time."""
    return isinstance(word, str) or isinstance(word, dict) and isinstance(word.get("dynamic"), str)


class RunTime:
    """A word the shell builds at run time, with the literal text before its first expansion
    (`--notes=` of `--notes="$NOTES"`, `dist/` of `dist/*.zip`)."""

    def __init__(self, prefix):
        self.prefix = prefix if isinstance(prefix, str) else ""


def long_name(name, names):
    """The long option a unique prefix stands for (`--mes` for `--message`), else the name."""
    matches = [option for option in names if option.startswith("--") and option.startswith(name)]
    return matches[0] if len(name) > 2 and name not in names and len(matches) == 1 else name


def read_options(args, takes_value):
    """(positionals, {option: value}) as getopt reads them: `-abc` is three options, a short
    option that takes a value takes the rest of its word or the next one, `--name=value`
    or `--name value` for a long one, and `--` ends the options."""
    found, options, index = [], {}, 0
    while index < len(args):
        word, index = args[index], index + 1
        if word == "--":
            found += [None if isinstance(rest, RunTime) else rest for rest in args[index:]]
            break
        if isinstance(word, RunTime):
            word = run_time_word(word.prefix, takes_value)
            if word is None:
                found.append(None)
                continue
            if word == UNKNOWN_OPTION:
                options[UNKNOWN_OPTION] = None
                continue
        if not word.startswith("-") or word == "-":
            found.append(word)
        elif word.startswith("--"):
            name, has_value, value = word.partition("=")
            name = long_name(name, takes_value)
            if not has_value and name in takes_value and index < len(args):
                value, index = args[index], index + 1
            options[name] = value
        else:
            for at in range(1, len(word)):
                name = "-" + word[at]
                if name not in takes_value:
                    options[name] = ""
                    continue
                value = word[at + 1:]
                if not value and index < len(args):
                    value, index = args[index], index + 1
                options[name] = value
                break
    return found, {name: None if is_run_time(value) else value for name, value in options.items()}


def is_run_time(value):
    """Whether an option's value is built at run time: a whole word, or the rest of one."""
    return isinstance(value, RunTime) or isinstance(value, str) and RUN_TIME_VALUE in value


def run_time_word(prefix, takes_value):
    """How `read_options` reads a word built at run time, from its literal start: None for a
    positional (`dist/*.zip`), the start plus RUN_TIME_VALUE for an option whose value is built
    at run time (`--notes=$NOTES`, `-m"$MSG"`), or UNKNOWN_OPTION when the start cannot name its
    option (`$FLAG`, `-$F`, `--ta$X`), so any option may have been given."""
    if prefix and not prefix.startswith("-"):
        return None
    if prefix.startswith("--"):
        named = "=" in prefix and prefix.partition("=")[0] != "--"
        return prefix + RUN_TIME_VALUE if named else UNKNOWN_OPTION
    if any("-" + char in takes_value for char in prefix[1:]):
        return prefix + RUN_TIME_VALUE
    return UNKNOWN_OPTION


def program(words):
    """The command's program name, without a Windows extension, or "" when unknown."""
    if not words or not isinstance(words[0], str):
        return ""
    name = os.path.basename(words[0].replace("\\", "/")).lower()
    return re.sub(r"\.(exe|cmd|bat|com)$", "", name)


def runs_in(words):
    """The command, and each git or gh command a wrapper in it may run (`env A=1 git tag`,
    `sudo gh release create`); a tool that only reads or prints text runs none."""
    if program(words) in TEXT_TOOLS:
        return [words]
    return [words] + [words[i:] for i in range(1, len(words)) if program(words[i:]) in ("git", "gh")]


def git_subcommand(words):
    """The words after `git` and its global options, or None when this is not git."""
    if program(words) != "git":
        return None
    rest = words[1:]
    while rest and isinstance(rest[0], str) and rest[0].startswith("-"):
        rest = rest[2:] if rest[0] in GIT_GLOBAL_VALUE else rest[1:]
    return rest


def release_from_git(words):
    """(version, ref) when the words create a git tag, else None."""
    rest = git_subcommand(words)
    if not rest or rest[0] != "tag":
        return None
    found, options = read_options(rest[1:], TAG_VALUE)
    named = {long_name(option, TAG_NOT_CREATING) for option in options}
    if not found or UNKNOWN_OPTION in options or TAG_NOT_CREATING & named:
        return None
    return found[0], (found[1] if len(found) > 1 else "HEAD")


class OutOfTime(Exception):
    """The hook's time budget ran out before the release could be checked."""


def git_output(project, *args):
    """What git prints, or "" when it fails. Running out of time is not an answer: it raises."""
    git = trusted_program("git", project)
    if not git:
        return ""
    try:
        out = subprocess.run([git, *args], cwd=project, capture_output=True, text=True,
                             encoding="utf-8", errors="replace", timeout=seconds_left())
    except subprocess.TimeoutExpired:
        raise OutOfTime() from None
    except (OSError, subprocess.SubprocessError):
        return ""
    return out.stdout.strip() if out.returncode == 0 else ""


def branch_ref(project, branch):
    """The branch as a ref git can read here: local, then on origin, else the current commit."""
    for ref in (branch, "origin/" + branch):
        if git_output(project, "rev-parse", "--verify", "--quiet", ref + "^{commit}"):
            return ref
    return "HEAD"


def release_ref(project, version, options):
    """The commit `gh release create` releases: the version's tag when it exists, else the
    `--target` branch or commit, else the current one; None when the target is built at run time."""
    tag = "refs/tags/" + version
    if git_output(project, "rev-parse", "--verify", "--quiet", tag + "^{commit}"):
        return tag
    if "--target" not in options:
        return "HEAD"
    target = options["--target"]
    return branch_ref(project, target) if target else None


def past_gh_options(words, index):
    """The index of the first word from `index` on that is not a gh option or its value."""
    while index < len(words) and isinstance(words[index], str) and words[index].startswith("-"):
        index += 2 if words[index] in GH_GROUP_VALUE else 1
    return index


def gh_action(words):
    """(group, action, the action's arguments) of a gh command, skipping the repo option before
    the group or the action (`gh -R owner/repo release create`); None when this is not gh."""
    if program(words) != "gh":
        return None
    group = past_gh_options(words, 1)
    action = past_gh_options(words, group + 1)
    if action >= len(words):
        return None
    return words[group], words[action], words[action + 1:]


def release_from_gh(words, project):
    """(version, ref) when the words create a release or a release branch's PR, else None."""
    parts = gh_action(words)
    if not parts:
        return None
    group, action, args = parts
    if group == "release" and action in GH_CREATE:
        found, options = read_options(args, RELEASE_VALUE)
        if not found or found[0] is None or UNKNOWN_OPTION in options:
            return None
        return found[0], release_ref(project, found[0], options)
    if group == "pr" and action in GH_CREATE:
        _, options = read_options(args, PR_VALUE)
        if UNKNOWN_OPTION in options:
            return None
        named = "--head" if "--head" in options else "-H"
        head = options.get(named)
        if named in options and head is None:
            return None
        branch = head.split(":")[-1] if head else git_output(project, "branch", "--show-current")
        match = RELEASE_BRANCH.fullmatch(branch)
        if not match:
            return None
        return match.group(1), (branch_ref(project, branch) if head else "HEAD")
    return None


def load_scheme(project):
    """(scheme, format) from the saved answers, or None when nothing is checked."""
    try:
        with open(os.path.join(project, ".bindwright", "project.json"), encoding="utf-8") as handle:
            advanced = json.load(handle).get("advanced")
    except (OSError, ValueError, AttributeError):
        return None
    if not isinstance(advanced, dict) or advanced.get("versioning") not in ("semver", "calver"):
        return None
    fmt = advanced.get("versionFormat")
    if advanced["versioning"] == "calver" and not isinstance(fmt, str):
        return None
    return advanced["versioning"], fmt


def check_script(project):
    """The repo's version check script, which setup writes beside this hook."""
    return os.path.join(project, ".github", "scripts", "version_check.py")


def check_release(project, scheme, fmt, version, ref):
    """The reasons the release is refused, or None when it may go ahead."""
    argv = [sys.executable, "-I", check_script(project), version, "--scheme", scheme, "--ref", ref]
    if scheme == "calver" and fmt:
        argv += ["--format", fmt]
    try:
        out = subprocess.run(argv, cwd=project, capture_output=True, text=True, encoding="utf-8",
                             errors="replace", timeout=seconds_left())
    except subprocess.TimeoutExpired:
        return OUT_OF_TIME
    except (OSError, subprocess.SubprocessError) as error:
        return f"the version check could not run: {error}"
    if out.returncode == 0:
        return None
    if out.returncode == 2 and out.stdout.strip():
        return out.stdout.strip()
    return f"the version check could not run: {(out.stderr or out.stdout).strip()}"


def refusal(command, shell, project):
    """Why the command's release is blocked, or None. A command that cannot make a release
    returns before anything that can fail; past that, a failure blocks with its reason."""
    if not may_be_release(command):
        return None
    try:
        return read_and_check(command, shell, project)
    except OutOfTime:
        return f"Blocked: this command may make a release, and {OUT_OF_TIME}"


def read_and_check(command, shell, project):
    """The block message for a command that may make a release, or None; raises OutOfTime."""
    project = git_output(project, "rev-parse", "--show-toplevel") or project
    scheme_and_format = load_scheme(project)
    if not scheme_and_format or not os.path.isfile(check_script(project)):
        return None
    scheme, fmt = scheme_and_format
    commands = shell_commands(command, shell, project)
    if commands is None:
        return UNREAD
    return first_refusal(commands, project, scheme, fmt)


def first_refusal(commands, project, scheme, fmt):
    """The block message for the first release in the commands the check refuses, or None."""
    shape = SEMVER_TAG if scheme == "semver" else CALVER_TAG
    for words in (run for words in commands for run in runs_in(words)):
        release = release_from_git(words) or release_from_gh(words, project)
        if not release or None in release or not shape.fullmatch(release[0]):
            continue
        reasons = check_release(project, scheme, fmt, *release)
        if reasons:
            return (f"Blocked release {release[0]}: its version does not fit the commits since "
                    f"the last release.\n{reasons}\nPick the version the commits need, or fix "
                    "the changelog, then run the command again.")
    return None


def main():
    try:
        data = json.loads(sys.stdin.buffer.read().decode("utf-8", "replace"))
    except ValueError:
        return 0
    if not isinstance(data, dict) or data.get("tool_name") not in ("Bash", "PowerShell"):
        return 0
    tool_input = data.get("tool_input")
    command = tool_input.get("command") if isinstance(tool_input, dict) else None
    if not isinstance(command, str):
        return 0
    # The folder the command runs in; refusal reads the repo it belongs to.
    places = (data.get("cwd"), os.environ.get("CLAUDE_PROJECT_DIR"))
    project = next((place for place in places if isinstance(place, str) and place), os.getcwd())
    shell = "powershell" if data.get("tool_name") == "PowerShell" else "bash"
    reason = refusal(command, shell, project)
    if not reason:
        return 0
    print(reason, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())

files..claude/scripts/research-adherence.py:
"""Count this session's code-research calls: FindWright versus plain text search.

Reads the newest transcript for the current directory under
~/.claude/projects/, or the transcript given as the first argument.
Run from the repo root at session close.

A plain search counts only when it looks for code inside the repo: a Grep
or Glob call, or a shell command that starts with a recursive search (grep
-r, rg, git grep, or a recursive listing piped into Select-String). Each
search is judged by what it reads: its file filters (globs, types,
-Include) when it has any, otherwise the files and folders it names, and a
folder by the files git tracks in it. ripgrep and ack also read a file
named beside a filter, so a code file named there counts. A search that
reads only docs, logs or data files, a filter on another command's output
(`... | grep x`), and
a search of folders outside the repo (a scratchpad, a package cache),
which the code-research tool has no index for, are not counted. When the
words cannot be read for sure, the search counts unless it runs outside
the repo and names nothing inside it, the side that never flatters the
figure.
"""
import glob
import json
import os
import re
import shlex
import subprocess
import sys

TOOL = re.compile(r"findwright")
BYPASS = "FINDWRIGHT_BYPASS:"
NON_CODE_EXTENSIONS = {"md", "mdx", "txt", "log", "json", "jsonl", "yaml", "yml", "csv"}
# ripgrep's and grep's file types for the same files.
NON_CODE_TYPES = {"md", "markdown", "txt", "json", "jsonl", "yaml", "csv", "log"}
SHELL_SEARCH = re.compile(r"^\s*(rg|ag|ack|git\s+grep)\s|^\s*grep\s(.*\s)?(-[a-zA-Z]*[rR]|--recursive)")
PS_LISTING = re.compile(r"^\s*(Get-ChildItem|gci|dir|ls)\s.*-Recurse", re.I)
PS_SEARCH = re.compile(r"^\s*(sls|Select-String)\s", re.I)
# Git Bash spells a Windows drive as /p/...; Python reads it as P:/...
GIT_BASH_DRIVE = re.compile(r"^/([a-zA-Z])/")
CD = re.compile(r"^\s*(cd|Set-Location|sl|pushd|popd)(?:\s+(.+?))?\s*$", re.I)
# Moves whose target the line cannot show: back (cd -, popd) or home (a bare cd).
RETURN_TARGETS = (None, "-")
REDIRECT = re.compile(r"^(?:\d*|&)[<>]")
# A redirect operator written apart from its target (`2> /dev/null`): the next word is the target.
BARE_REDIRECT = re.compile(r"^(?:\d*|&)(?:>>?|<)&?$")
WILDCARD = re.compile(r"[*?\[]")

# Options whose value narrows the files a search reads, written apart (`-g x`) or joined (`-gx`,
# `--glob=x`, `-Include:x`). Every other word only matters when it names a file or folder that exists.
FILTER_OPTIONS = ("-g", "--glob", "--iglob", "--include", "-t", "--type", "-include", "-filter",
                  "--exclude", "--exclude-dir", "-exclude")
# A git pathspec that leaves files out (`:!*.md`, `:^x`, `:(exclude)x`); it never says what is read.
EXCLUDE_PATHSPEC = re.compile(r"^['\"]?:(?:!|\^|\(exclude\))")
# Their values leave files out; they never say what the search reads.
EXCLUDE_OPTIONS = ("--exclude", "--exclude-dir", "-exclude")
TYPE_OPTIONS = ("-t", "--type")
# With none of these, a text search takes its pattern as a plain word.
PATTERN_OPTIONS = ("-e", "--regexp", "-f", "--file", "--files")
PATTERN_VALUE_OPTIONS = ("-e", "--regexp", "-f", "--file")
# Short flags that take no value in rg, grep, git grep, ag and ack alike, and more per tool. A word
# after any other option may be its value, so it never decides what a search reads.
FLAGS_WITHOUT_VALUE = "cFHhilLnosvw"
TOOL_FLAGS_WITHOUT_VALUE = {"grep": "EIPqRrx", "rg": "IPqSUuxz", "ag": "f"}
# Only these take a pattern file after `-f`: in ag it follows links, in ack it lists files.
PATTERN_FILE_TOOLS = ("grep", "rg")


def unquote_separators(command):
    """Blank out | ; & and newlines inside quotes, so a search pattern like "a|b" does not split the command."""
    out, quote = [], None
    for ch in command:
        if quote:
            quote = None if ch == quote else quote
            ch = " " if ch in "|;&\n" else ch
        elif ch in "'\"":
            quote = ch
        out.append(ch)
    return "".join(out)


def unquote(word):
    return word.strip("'\"")


def literal(word):
    """`word` unquoted. A quoted `~` stays a folder name, as Bash and a native tool leave it."""
    text = unquote(word)
    return "./" + text if word[:1] in "'\"" and text.startswith("~") else text


def resolve(path, base, expands_quoted_home=False):
    """The absolute, case-folded form of a path as a shell in `base` reads it.

    A PowerShell cmdlet (`Set-Location`, `Get-ChildItem`) reads `~` as the home folder even quoted."""
    path = os.path.expanduser(unquote(path) if expands_quoted_home else literal(path))
    if os.name == "nt":
        path = GIT_BASH_DRIVE.sub(lambda m: m.group(1) + ":/", path)
    return os.path.normcase(os.path.abspath(os.path.join(base, path)))


def is_outside(path, root):
    """True when `path` is neither the repo root nor anything under it."""
    try:
        return os.path.commonpath([path, root]) != root
    except ValueError:
        return True  # another drive


def is_wide(name):
    """True when a glob names no extension, so it narrows nothing by file kind (`*`, `docs/**`)."""
    return "." not in os.path.basename(unquote(name).rstrip("/\\"))


def is_code_name(name):
    """True when a file name or glob can match a code file, one whose extension is not a doc's."""
    name = unquote(name).rstrip("/\\")
    braces = re.search(r"\{([^}]*)\}$", name)
    endings = [name]
    if braces:
        endings = [name[:braces.start()] + part for part in braces.group(1).split(",")]
    for ending in endings:
        extension = ending.rsplit(".", 1)[-1].lower() if "." in os.path.basename(ending) else ""
        if extension not in NON_CODE_EXTENSIONS:
            return True
    return False


def tracked_files(root):
    """The tracked files, absolute and case-folded; every file there when git cannot list them."""
    try:
        command = ["git", "-C", root, "ls-files", "-z"]
        listed = subprocess.run(command, capture_output=True, check=True).stdout
        names = [n for n in listed.decode("utf-8", "replace").split("\0") if n]
    except (OSError, subprocess.CalledProcessError):
        names = []
        for folder, dirs, files in os.walk(root):
            dirs[:] = [d for d in dirs if d != ".git"]
            names += [os.path.relpath(os.path.join(folder, f), root) for f in files]
    return [os.path.normcase(os.path.abspath(os.path.join(root, n))) for n in names]


class Repo:
    """The repo a search is judged against: its root and, read once when needed, its code files."""

    def __init__(self, root):
        self.root = root
        self._code_files = None

    def code_files(self):
        if self._code_files is None:
            self._code_files = [f for f in tracked_files(self.root) if is_code_name(f)]
        return self._code_files

    def holds_code(self, path):
        """True when an in-repo file or folder is code, or cannot be told apart from code.

        A wildcard is judged by its name, never expanded: the folder it would expand in is a guess. One
        with no extension (`*`, `gui*`) can name anything in its folder, so the folder judges it."""
        if WILDCARD.search(os.path.basename(path)):
            return self.holds_code(os.path.dirname(path)) if is_wide(path) else is_code_name(path)
        if os.path.isdir(path):
            # Case-blind: macOS and Windows folders match whatever case the search typed.
            prefix = path.rstrip("\\/").lower() + os.sep
            return path == self.root or any(f.lower().startswith(prefix) for f in self.code_files())
        return is_code_name(path)


class Search:
    """What one search reads: the paths it names, and the globs and types that narrow its files."""

    def __init__(self, paths=(), globs=(), types=(), is_sure=True, filters_named_files=True):
        self.paths = list(paths)
        # ripgrep and ack search a file named on the command line whatever their -g or -t says.
        self.filters_named_files = filters_named_files
        # False when the words cannot be told apart: then only where the search runs and what
        # its words point at are judged.
        self.is_sure = is_sure
        # A negated glob (`!*.md`) leaves files out; it never says what the search reads.
        globs = [g for g in map(unquote, globs) if g]
        self.globs = [g for g in globs if not g.startswith("!") and not is_wide(g)]
        self.types = [unquote(t).lower() for t in types]

    def reads_code(self, base, repo):
        """True when the search reads code inside the repo, with paths read from `base`."""
        named = [resolve(p, base) for p in self.paths]
        if not self.is_sure:
            # Counted unless it runs outside the repo and no word it names lies inside it.
            return not is_outside(base, repo.root) or any(
                not is_outside(p, repo.root) for p, word in zip(named, self.paths)
                if os.path.exists(p) or re.search(r"[/\\]", word))
        # A word with a folder in it is a named path even once it is gone (a deleted temp clone).
        paths = [p for p, word in zip(named, self.paths)
                 if os.path.exists(p) or WILDCARD.search(os.path.basename(p))
                 or re.search(r"[/\\]", word)] or [base]
        inside = [p for p in paths if not is_outside(p, repo.root)]
        if not inside:
            return False
        if self.globs or self.types:
            return (any(is_code_name(g) for g in self.globs)
                    or any(t not in NON_CODE_TYPES for t in self.types)
                    or (not self.filters_named_files and any(names_code_file(p, repo) for p in inside)))
        return any(repo.holds_code(p) for p in inside)


def names_code_file(path, repo):
    """True when a named path is a code file, or a wildcard that can name one, judged as `holds_code` does."""
    if WILDCARD.search(os.path.basename(path)):
        return repo.holds_code(path)
    return os.path.isfile(path) and is_code_name(path)


def split_words(head):
    """The words of one command, with quotes kept; redirects, their targets and a trailing
    comment (a bypass marker) dropped."""
    # Not POSIX mode, which reads a backslash as an escape and would turn D:\scratch into
    # D:scratch; quotes stay on the words, and resolve() strips them.
    try:
        words = shlex.split(head, posix=False)
    except ValueError:
        words = head.split()
    kept, skip_next = [], False
    for word in words:
        if word.startswith("#"):
            break
        if skip_next:
            skip_next = False
        elif BARE_REDIRECT.match(word):
            skip_next = True
        elif not REDIRECT.match(word):
            kept.append(word)
    return kept


def filter_of(word, words, tool):
    """(option, value) when `word` is a filter option, taking a separate value from `words`."""
    for option in FILTER_OPTIONS:
        if len(option) == 2 and tool != "rg":
            continue  # `-g` and `-t` filter files only in ripgrep (`ag -t` searches all text)
        # Short options keep their case (`-T` excludes a type); long and PowerShell ones do not.
        spelled = word if len(option) == 2 else word.lower()
        if spelled == option:
            return option, words.pop(0) if words else ""
        if spelled.startswith(option) and spelled[len(option):len(option) + 1] in ("=", ":"):
            return option, word[len(option) + 1:]
        if len(option) == 2 and spelled.startswith(option):
            return option, word[2:]
    return None


def takes_no_value(word, tool):
    """True when `word` is a cluster of short flags that take no value in `tool`."""
    flags = FLAGS_WITHOUT_VALUE + TOOL_FLAGS_WITHOUT_VALUE.get(tool, "")
    return bool(re.fullmatch(r"-[A-Za-z]+", word)) and all(letter in flags for letter in word[1:])


def filter_values(value, rest):
    """The values of one filter option; a PowerShell list (`"*.md","*.py"`, `*.md, *.py`) arrives
    as several words, taken from `rest`."""
    while rest and (value.endswith(",") or rest[0].startswith(",")):
        value += rest.pop(0)
    # A comma inside braces belongs to the glob (`*.{md,txt}`), not the list.
    return [v for v in (unquote(v.strip()) for v in re.split(r",(?![^{}]*\})", value)) if v]


def read_words(rest, tool):
    """(plain, globs, types, pattern_given, has_unknown) for a command's words after its name.
    The plain words include an option's `=` or `:` value. has_unknown is True when an option is
    none the script knows: a filter, a pattern option, `--`, or a cluster of short flags that take
    no value in `tool`."""
    plain, globs, types = [], [], []
    pattern_given = has_unknown = False
    while rest:
        word = rest.pop(0)
        if word == "--":  # the end of the options: every word after it is plain
            plain += rest
            break
        found = filter_of(word, rest, tool) if word.startswith("-") else None
        if found:
            option, value = found
            values = filter_values(value, rest)  # an exclude list is read whole, then left out
            if option not in EXCLUDE_OPTIONS:
                (types if option in TYPE_OPTIONS else globs).extend(values)
        elif (word in PATTERN_OPTIONS or word.split("=", 1)[0] in PATTERN_VALUE_OPTIONS) and (
                word != "-f" or tool in PATTERN_FILE_TOOLS):
            pattern_given = True
            if word in PATTERN_VALUE_OPTIONS and rest:
                rest.pop(0)  # the pattern, or the file that holds it
        elif word.startswith("-"):
            joined = re.split(r"[=:]", word, maxsplit=1)
            if len(joined) == 2:
                plain.append(joined[1])
            has_unknown = has_unknown or len(joined) == 2 or not takes_no_value(word, tool)
        else:
            plain.append(word)
    return plain, globs, types, pattern_given, has_unknown


def words_search(words, is_text_search=True):
    """What a text search or a recursive listing reads: its filters, and every word that may name a path.

    A text search is read for sure only when every option in it is one `read_words` knows; then it
    takes its first plain word as its pattern unless `-e`, `-f` or `--files` gives one, and
    `Search.reads_code` keeps only the words that name a file or folder that exists. With any other
    option the words cannot be read for sure, and only where the search runs and what its words
    point at are judged."""
    if words[:2] == ["git", "grep"]:
        words = words[1:]
    tool = words[0] if words else ""
    # An option's joined value is cut from it; any other word stays whole (`D:\proj\src`).
    unsure = Search([unquote(re.split(r"[=:]", w, maxsplit=1)[-1] if w.startswith("-") else w)
                     for w in words[1:]], is_sure=False)
    if any(word.count('"') % 2 or word.count("'") % 2 for word in words):
        return unsure  # a quote the word does not close: `--regexp="see docs"` split at the space
    plain, globs, types, pattern_given, has_unknown = read_words(words[1:], tool)
    if is_text_search:
        if has_unknown:
            return unsure  # an option it does not know may take a value or give the pattern
        named = plain[0 if pattern_given else 1:]
    else:
        # A PowerShell listing's comma list is several paths.
        named = [piece for word in plain for piece in word.split(",") if piece]
    paths = []
    for piece in (p for p in named if not EXCLUDE_PATHSPEC.match(p)):
        # A text search's positional wildcard (`*.md`) is one more path, judged beside the folders
        # named with it; a listing's is its -Filter.
        is_filter = (not is_text_search and WILDCARD.search(piece)
                     and not re.search(r"['\"/\\]", piece))
        # A text search's word keeps its quotes for `resolve`: a native tool takes a quoted `~` as a
        # folder name. A listing is a cmdlet, which reads `~` as home either way.
        (globs if is_filter else paths).append(piece if is_text_search else unquote(piece))
    return Search(paths, globs, types, filters_named_files=tool not in ("rg", "ack"))


def shell_search(command, repo, is_powershell=False):
    """True when a command line runs a code search of its own inside the repo."""
    base = repo.root
    for part in re.split(r"&&|\|\||;|\n", unquote_separators(command)):
        stages = part.split("|")
        head = stages[0]
        moved = CD.match(head)
        if moved:
            # The repo root is the folder such a move most likely returns to, and reading it so
            # keeps the search counted, the side that never flatters the figure.
            words = split_words(moved.group(2) or "")
            target = words[0] if words else None
            back = moved.group(1).lower() == "popd" or target in RETURN_TARGETS
            base = repo.root if back else resolve(" ".join(words), base, is_powershell)
            continue
        if SHELL_SEARCH.search(head):
            search = words_search(split_words(head))
        elif PS_LISTING.search(head) and any(PS_SEARCH.search(s) for s in stages[1:]):
            search = words_search(split_words(head), is_text_search=False)
        else:
            continue
        if search.reads_code(base, repo):
            return True
    return False


def tool_search(name, args):
    """What a Grep or Glob call reads."""
    path = str(args.get("path") or "")
    if name == "Grep":
        types = [str(args["type"])] if args.get("type") else []
        return Search([path] if path else [], [str(args.get("glob") or "")], types)
    pattern = str(args.get("pattern") or "")
    # A pattern can carry its own folder: an absolute one, or a relative one under the path.
    static = re.split(r"[*?\[{]", pattern, maxsplit=1)[0]
    folder = os.path.dirname(static) if os.path.dirname(static) else ""
    paths = [os.path.join(path, folder)] if folder else [path] if path else []
    return Search(paths, [pattern])


def classify(name, args, root=None):
    """'research', 'fallback', 'bypass', or None for a call that is not a code search.

    `root` is the repo root as `repo_root()` gives it; by default, the folder this runs from."""
    repo = root if isinstance(root, Repo) else Repo(root or repo_root())
    if TOOL.search(name):
        return "research"
    if name in ("Grep", "Glob"):
        return "fallback" if tool_search(name, args).reads_code(repo.root, repo) else None
    if name in ("Bash", "PowerShell"):
        command = args.get("command", "")
        if shell_search(command, repo, is_powershell=name == "PowerShell"):
            return "bypass" if BYPASS in command else "fallback"
    return None


def transcript():
    if len(sys.argv) > 1:
        return sys.argv[1]
    slug = re.sub(r"[^A-Za-z0-9]", "-", os.getcwd())
    files = glob.glob(os.path.join(os.path.expanduser("~"), ".claude", "projects", slug, "*.jsonl"))
    if not files:
        sys.exit(f"No transcript found for {os.getcwd()}; run this from the repo root.")
    return max(files, key=os.path.getmtime)


def tool_calls(path):
    with open(path, encoding="utf-8") as f:
        for line in f:
            try:
                entry = json.loads(line)
            except ValueError:
                continue
            content = (entry.get("message") or {}).get("content")
            if entry.get("type") != "assistant" or not isinstance(content, list):
                continue
            for part in content:
                if isinstance(part, dict) and part.get("type") == "tool_use":
                    yield part.get("name", ""), part.get("input") or {}


def repo_root():
    """The folder this runs from, the repo root, in the form `classify` compares."""
    return os.path.normcase(os.path.abspath(os.getcwd()))


def main():
    counts = {"research": 0, "fallback": 0, "bypass": 0}
    repo = Repo(repo_root())
    for name, args in tool_calls(transcript()):
        kind = classify(name, args, repo)
        if kind:
            counts[kind] += 1
    total = counts["research"] + counts["fallback"]
    ratio = f"{100 * counts['research'] // total}%" if total else "n/a"
    print(f"FindWright: {counts['research']} calls, plain code searches: {counts['fallback']} "
          f"(plus {counts['bypass']} marked bypasses) -> {ratio}")


if __name__ == "__main__":
    main()

files..github/scripts/pin_check.py:
"""Lists the pinned versions in the workflows that are behind the newest releases.

Pins keep a PR's result stable; this says when they fall behind. The weekly
pin-check workflow looks up the newest releases and passes them in:

    pin_check.py --cli 2.1.310 --action-sha <40 hex> --action-version v1.0.220 FILE...

Prints a Markdown list of the pins that are behind, one line per pinned value
with every place it is pinned, or nothing when every pin is current. Exits 1 on
bad arguments or a file it cannot read.

Pins it reads:
- the CLI version a workflow installs: `CLI_VERSION: "2.1.300"` or
  `PINNED_VERSION: "2.1.299"`;
- the review action's commit: `uses: anthropics/claude-code-action@<sha>`, with
  the version it names in the comment after it.

It also lists every action a workflow uses by a tag or branch instead of a
commit (`uses: actions/checkout@v6`): a tag can be moved to other code.

The deep review runs it on a PR's diff to look up, on GitHub, each action pin
the PR adds, since the reviewer's own tools cannot reach other repos:

    git diff BASE...HEAD -- '*.yml' '*.yaml' | pin_check.py added

Prints a Markdown line per added pin, verified when a release tag its comment
names points to its commit and not verified otherwise, or nothing when the
diff adds no pin.
"""

import json
import re
import subprocess
import sys
import time

CLI = re.compile(r'^\s*(?:CLI_VERSION|PINNED_VERSION):\s*"?(\d+(?:\.\d+)*)"?\s*(?:#.*)?$')
ACTION = re.compile(r"^\s*(?:-\s+)?uses:\s*anthropics/claude-code-action@([0-9a-f]{40})\b(?:\s*#\s*(.*))?$")
DOCKER = re.compile(r"^\s*(?:-\s+)?uses:\s*['\"]?docker://([^\s'\"#]+)")
USES = re.compile(r"^\s*(?:-\s+)?uses:\s*['\"]?([\w.-]+/[\w./-]+)@([^\s'\"#]+)")
VERSION = re.compile(r"\d+(?:\.\d+)*")
SHA = re.compile(r"[0-9a-f]{40}")
REPO = re.compile(r"[A-Za-z0-9_.-]{1,39}/[A-Za-z0-9_.-]{1,100}")
TAG = re.compile(r"(?<![\w.-])(v\d+(?:\.\d+)*|\d+\.\d+(?:\.\d+)*)(?![\w.-])", re.ASCII)
MAX_TAG_LENGTH = 40
MAX_PINS = 40
MAX_TAGS = 4
MAX_PEELS = 3
SEPARATORS = " \t\r"


def _tuple(version):
    return tuple(int(p) for p in version.split("."))


def pins(name, text):
    """[(kind, value, label, "file:line")] for every pin in one file."""
    found = []
    for n, line in enumerate(text.splitlines(), 1):
        m = CLI.match(line)
        if m:
            found.append(("cli", m.group(1), m.group(1), "%s:%d" % (name, n)))
            continue
        m = ACTION.match(line)
        if m:
            label = (m.group(2) or "").strip() or m.group(1)[:12]
            found.append(("action", m.group(1), label, "%s:%d" % (name, n)))
    return found


def floating(name, text):
    """["owner/repo@ref at file:line"] for every action used by a ref that is not a commit."""
    found = []
    for n, line in enumerate(text.splitlines(), 1):
        m = USES.match(line)
        commit = SHA.fullmatch(m.group(2)) if m else None
        if m and not (commit and ends_value(line, m)):
            # A commit id with text glued after it is shown with that text, the ref the runner uses.
            ref = line[m.start(2):].split()[0] if commit else m.group(2)
            found.append("`%s@%s` at `%s:%d`" % (m.group(1), ref, name, n))
            continue
        m = DOCKER.match(line)
        if m and "@sha256:" not in m.group(1):
            found.append("`docker://%s` at `%s:%d`" % (m.group(1), name, n))
    return found


def ends_value(text, m):
    """True when the YAML value ends right after the commit id (or the closing quote of a
    quoted value), with only YAML's separators (space, tab, CR) and a `#` comment after it.
    Anything else on the line (`#x` glued on, a no-break space, a second word) is part of
    the ref the runner uses, so that ref is not the commit."""
    rest = text[m.end(2):]
    opened = text[m.start(1) - 1] if text[m.start(1) - 1] in "'\"" else ""
    if opened:
        if rest[:1] != opened:
            return False
        rest = rest[1:]
    after = rest.lstrip(SEPARATORS)
    return not after or (after.startswith("#") and len(after) < len(rest))


def added_pins(diff):
    """[(owner/repo, sha, [tags])] for each action a diff adds by commit, with
    the first MAX_TAGS release tags its comment names (`# v6 (v6.1.0)`). Only
    these checked fields leave the diff: no file name or other PR text."""
    found = []
    for line in diff.split("\n"):
        m = USES.match(line[1:]) if line.startswith("+") else None
        if not m or not SHA.fullmatch(m.group(2)) or not ends_value(line[1:], m):
            continue
        repo = "/".join(m.group(1).split("/")[:2])
        if not REPO.fullmatch(repo) or any(p in (".", "..") for p in m.group(1).split("/")):
            continue
        tags = [t for t in dict.fromkeys(TAG.findall(line.partition("#")[2])) if len(t) <= MAX_TAG_LENGTH]
        tags = tags[:MAX_TAGS]
        entry = (repo, m.group(2), tags)
        if entry not in found:
            found.append(entry)
    return found


def tag_commit(repo, tag, fetch):
    """The commit a release tag points to, peeling annotated tags; None when the
    tag is missing or does not end at a commit. `fetch(path)` returns the API's
    JSON, or None on 404."""
    obj = _object(fetch("repos/%s/git/ref/tags/%s" % (repo, tag)))
    for _ in range(MAX_PEELS):
        if not obj or obj["type"] != "tag":
            break
        obj = _object(fetch("repos/%s/git/tags/%s" % (repo, obj["sha"])))
    return obj["sha"] if obj and obj["type"] == "commit" else None


def _object(reply):
    """A reply's `object` as {"type", "sha"} when its id is a full commit-style id, else None."""
    obj = reply.get("object") if isinstance(reply, dict) else None
    if isinstance(obj, dict) and isinstance(obj.get("sha"), str) and SHA.fullmatch(obj["sha"]):
        return {"type": obj.get("type"), "sha": obj["sha"]}
    return None


def provenance(found, fetch):
    """A Markdown line per added pin with the workflow's verdict: verified when a
    release tag its comment names points to its commit. Each (repo, tag) is
    looked up once, however many pins name it."""
    lines, cache = [], {}
    for repo, sha, tags in found[:MAX_PINS]:
        verdict = "not verified: its comment names no release tag" if not tags else ""
        for tag in tags:
            if (repo, tag) not in cache:
                try:
                    cache[repo, tag] = tag_commit(repo, tag, fetch)
                except LookupError:
                    cache[repo, tag] = LookupError
            if cache[repo, tag] == sha:
                verdict = "verified: tag `%s` points to this commit" % tag
                break
            if cache[repo, tag] is LookupError:
                verdict = "not verified: a lookup failed"
        lines.append("- `%s@%s`: %s." % (repo, sha, verdict or "not verified: no tag it names points to this commit"))
    if len(found) > MAX_PINS:
        lines.append("- %d more pins were not looked up." % (len(found) - MAX_PINS))
    return "".join(line + "\n" for line in lines)


def gh_fetch(path):
    """`gh api <path>` as JSON; None on 404. Tries twice, then raises LookupError."""
    for attempt in range(2):
        try:
            out = subprocess.run(["gh", "api", path], capture_output=True, text=True, timeout=15)
        except (OSError, subprocess.TimeoutExpired):
            out = None
        if out is not None and out.returncode == 0:
            try:
                return json.loads(out.stdout)
            except ValueError:
                pass
        elif out is not None and "HTTP 404" in out.stderr:
            return None
        if attempt == 0:
            time.sleep(3)
    raise LookupError(path)


def behind(found, cli, action_sha):
    """The pins older than the newest CLI or not on the newest action commit,
    grouped by pinned value: [(kind, label, [places])] in first-seen order."""
    groups = {}
    for kind, value, label, place in found:
        old = _tuple(value) < _tuple(cli) if kind == "cli" else value != action_sha
        if old:
            groups.setdefault((kind, value), [label, []])[1].append(place)
    return [(kind, label, places) for (kind, _), (label, places) in groups.items()]


def report(stale, cli, action_version):
    newest = {"cli": "CLI " + cli, "action": "action " + action_version}
    what = {"cli": "CLI", "action": "Review action"}
    return "".join("- %s `%s` is behind the newest %s: %s\n"
                   % (what[kind], label, newest[kind], ", ".join("`%s`" % p for p in places))
                   for kind, label, places in stale)


def _option(args, name):
    if name not in args or args.index(name) + 1 == len(args):
        raise ValueError("%s needs a value" % name)
    i = args.index(name)
    value = args[i + 1]
    del args[i:i + 2]
    return value


def main(argv):
    args = list(argv)
    if args == ["added"]:
        sys.stdout.write(provenance(added_pins(sys.stdin.read()), gh_fetch))
        return 0
    try:
        cli = _option(args, "--cli")
        sha = _option(args, "--action-sha")
        version = _option(args, "--action-version")
        if not VERSION.fullmatch(cli) or not SHA.fullmatch(sha) or not args:
            raise ValueError("usage: pin_check.py --cli X.Y.Z --action-sha SHA --action-version V FILE...")
        found, unpinned = [], []
        for name in args:
            with open(name, encoding="utf-8") as fh:
                text = fh.read()
            found += pins(name, text)
            unpinned += floating(name, text)
    except (ValueError, OSError) as e:
        print("pin_check: %s" % e, file=sys.stderr)
        return 1
    sys.stdout.write(report(behind(found, cli, sha), cli, version))
    sys.stdout.write("".join("- Action %s is not pinned to a commit\n" % u for u in unpinned))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

files..github/scripts/size_check.py:
#!/usr/bin/env python3
"""Code-size check with a ratchet.

Measures the mechanical rows of `.claude/rules/code-size.md` against its own
tables, so the limits live in one place: file length, line length, and, per
function, length, cyclomatic complexity and parameter count. Nesting depth,
lambdas and the rule's exceptions are left to review.

A hard breach listed in `.github/size-check/baseline.txt` is tolerated while
it does not grow; a new breach, or growth of a listed one, fails. Breaches
the project accepts for good go in `.github/size-check/exceptions.txt` with a
reason. Both files hold `path|construct|name|value-or-reason` lines, `#` for
comments; `*` as the name covers every name in that file and construct.

Usage:
  python3 .github/scripts/size_check.py                  # exit 1 on a new or grown breach
  python3 .github/scripts/size_check.py --write-baseline # record today's hard breaches
  python3 .github/scripts/size_check.py --report         # also list tolerated and soft ones

Function rows need lizard (pip install lizard), from this Python or from the
environment setup installs it in, LIZARD_VENV. Without it they are skipped
and the check fails, so a missing row never reads as a pass.
"""

import argparse
import functools
import glob
import os
import re
import subprocess
import sys

ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".."))
RULE = os.path.join(ROOT, ".claude", "rules", "code-size.md")
BASELINE = os.path.join(ROOT, ".github", "size-check", "baseline.txt")
EXCEPTIONS = os.path.join(ROOT, ".github", "size-check", "exceptions.txt")
# Where setup installs lizard when this Python refuses `pip install --user`
# because the system or Homebrew manages it (PEP 668).
LIZARD_VENV = os.path.join(os.path.expanduser("~"), ".bindwright", "size-check-venv")

# The extensions each row of the rule's language table covers. "Other" takes
# every extension in the rule's `paths:` list that no named row claims.
LANGUAGE_EXTENSIONS = {
    "C / C++": (".c", ".cc", ".cpp", ".cxx", ".h", ".hh", ".hpp"),
    "C# / Java / Kotlin": (".cs", ".java", ".kt", ".kts"),
    "Dart": (".dart",),
    "GDScript": (".gd",),
    "Go": (".go",),
    "JavaScript / TypeScript": (".js", ".jsx", ".mjs", ".cjs", ".ts", ".tsx"),
    "Python": (".py",),
    "Rust": (".rs",),
}
# Generated and vendored code is out of scope (exception 1).
SKIP_DIRS = {"node_modules", "vendor", "third_party", "dist", "build", "generated"}
TEST_DIRS = {"test", "tests", "__tests__", "spec", "specs"}
TEST_NAME = re.compile(r"^test_|_test\.|\.test\.|\.spec\.|_spec\.")
TEST_FILE_FACTOR = 1.5


def limit_pair(cell):
    """(soft, hard) from a cell such as "800 (.h 400) / 1 500 (.h 800)".
    Variants in parentheses are left to review."""
    plain = re.sub(r"\([^)]*\)", "", cell)
    plain = re.sub(r"(?<=\d) (?=\d{3}\b)", "", plain)
    numbers = [int(n) for n in re.findall(r"\d+", plain)]
    return (numbers[0], numbers[1]) if len(numbers) >= 2 else None


def rule_extensions(text):
    """Every extension the rule's `paths:` frontmatter names."""
    head = text.split("\n---", 2)[0] if text.startswith("---") else ""
    found = []
    for braces in re.findall(r"\*\.\{([^}]*)\}", head):
        found += ["." + e.strip() for e in braces.split(",") if e.strip()]
    found += ["." + e for e in re.findall(r"\*\.([A-Za-z0-9]+)\b", head)]
    return sorted(set(found))


def table_rows(text):
    """Cells of every Markdown table row that is not a header or separator."""
    rows = []
    for line in text.splitlines():
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if not line.lstrip().startswith("|") or cells[0] in ("Construct", "Language"):
            continue
        if all(set(c) <= set("-: ") for c in cells):
            continue
        rows.append(cells)
    return rows


def read_rule(text):
    """({"params": pair, "ccn": pair}, {ext: {"file", "function", "line"}}, notes)."""
    shared, by_ext, notes, other, claimed = {}, {}, [], None, set()
    for cells in table_rows(text):
        if len(cells) == 3 and cells[0].startswith("Parameters"):
            shared["params"] = limit_pair(cells[1] + " / " + cells[2])
        elif len(cells) == 3 and cells[0].startswith("Cyclomatic"):
            shared["ccn"] = limit_pair(cells[1] + " / " + cells[2])
        elif len(cells) == 4:
            limits = {"file": limit_pair(cells[1]), "function": limit_pair(cells[2]), "line": limit_pair(cells[3])}
            if cells[0] == "Other":
                other = limits
            elif cells[0] in LANGUAGE_EXTENSIONS:
                by_ext.update({e: limits for e in LANGUAGE_EXTENSIONS[cells[0]]})
                claimed.update(LANGUAGE_EXTENSIONS[cells[0]])
            else:
                notes.append(f"the rule's row {cells[0]!r} names no known extensions; add it to LANGUAGE_EXTENSIONS")
    if other:
        # Every listed extension without a row of its own, so a language the
        # rule's table leaves out is still measured.
        by_ext.update({e: other for e in rule_extensions(text) if e not in claimed})
    return shared, by_ext, notes


def is_test(path):
    parts = path.split("/")
    return any(p in TEST_DIRS for p in parts[:-1]) or TEST_NAME.search(parts[-1]) is not None


def tracked_files(by_ext):
    # -z: paths come back raw, not quoted and escaped when they hold non-ASCII.
    out = subprocess.run(["git", "ls-files", "-z"], cwd=ROOT, capture_output=True, text=True, check=True,
                         encoding="utf-8")
    return [f for f in out.stdout.split("\0")
            if os.path.splitext(f)[1] in by_ext and not SKIP_DIRS.intersection(f.split("/")[:-1])]


def venv_site_packages():
    """The site-packages folders of LIZARD_VENV, in its Windows and POSIX layouts."""
    return (glob.glob(os.path.join(LIZARD_VENV, "Lib", "site-packages"))
            + sorted(glob.glob(os.path.join(LIZARD_VENV, "lib", "python3*", "site-packages"))))


@functools.lru_cache(maxsize=None)
def import_lizard():
    """The lizard module, from this Python or from LIZARD_VENV; None when neither has it."""
    try:
        import lizard
    except ImportError:
        # lizard is pure Python, so a copy installed for another Python 3 version still imports.
        sys.path.extend(venv_site_packages())
        try:
            import lizard
        except ImportError:
            return None
    return lizard


def functions(path):
    """(name, length, ccn, params) per function; False for a language lizard
    does not read, None when lizard is missing."""
    lizard = import_lizard()
    if lizard is None:
        return None
    if lizard.get_reader_for(path) is None:
        return False
    full = os.path.join(ROOT, path)
    if path.endswith((".ts", ".tsx")):
        found = typescript_functions(lizard, full)
    else:
        found = lizard.analyze_file(full).function_list
    return [(f.name, f.end_line - f.start_line + 1, f.cyclomatic_complexity, param_count(path, f)) for f in found]


OPENERS, CLOSERS = "([{", ")]}"
# A slash after one of these, or at the start of a line, opens a regex literal.
# Not after "}" or "<": in JSX those come before the slash of a closing tag.
REGEX_AFTER = "(,=:[!&|?{;+-*%~^"
# Modes that end with their line: strings, and regex literals ("/", "/[" in a class).
LINE_MODES = ("'", '"', "/", "/[")


def _scan_code(line, at):
    """One step through code from index `at`: (next index, the mode that
    starts there: "block", a quote, "/" for a regex literal, or None)."""
    pair = line[at:at + 2]
    if pair == "//":
        return len(line), None
    if pair == "/*":
        return at + 2, "block"
    if line[at] in "'\"`":
        return at + 1, line[at]
    before = line[:at].rstrip()
    if line[at] == "/" and (not before or before[-1] in REGEX_AFTER or before.endswith("return")):
        return at + 1, "/"
    return at + 1, None


def _scan_literal(line, at, mode):
    """One step inside a comment, string or regex literal: (next index, mode)."""
    c = line[at]
    if mode == "block":
        return (at + 2, "code") if line[at:at + 2] == "*/" else (at + 1, mode)
    if c == "\\":
        return at + 2, mode
    if mode in ("/", "/["):
        if c == "[" or c == "]":
            return at + 1, "/[" if c == "[" else "/"
        return at + 1, "code" if mode == "/" and c == "/" else mode
    return at + 1, "code" if c == mode else mode


def _scan_line(line, state):
    """Carries the scan through one line. `state` is [depth, mode, templates]:
    bracket depth in code, the mode the line ends in ("code", "block" or "`")
    and the depths where each open template's `${` returns."""
    depth, mode, templates = state
    i = 0
    while i < len(line):
        c = line[i]
        if mode == "`" and line[i:i + 2] == "${":
            templates.append(depth)
            depth, mode, i = depth + 1, "code", i + 2
        elif mode != "code":
            i, mode = _scan_literal(line, i, mode)
        elif c == "}" and templates and depth - 1 == templates[-1]:
            depth, mode, i = templates.pop(), "`", i + 1
        else:
            depth += (c in OPENERS) - (c in CLOSERS)
            i, opened = _scan_code(line, i)
            mode = opened or mode
    state[:] = [depth, "code" if mode in LINE_MODES else mode, templates]


def top_level_starts(text):
    """Lines that begin a top-level statement: column 0, not a closing
    bracket, at bracket depth 0 and outside strings, templates and comments.
    None when the brackets do not add up, so the file is read whole."""
    state, starts = [0, "code", []], []
    for i, line in enumerate(text.splitlines(keepends=True)):
        if state[:2] == [0, "code"] and line[:1] not in ("", " ", "\t", "\r", "\n", *CLOSERS):
            starts.append(i)
        _scan_line(line, state)
        if state[0] < 0:
            return None
    return starts


def top_level_chunks(text):
    """The text cut before every top-level statement. Blank lines stand in for
    the lines before each piece, so line numbers hold."""
    lines = text.splitlines(keepends=True)
    starts = top_level_starts(text) or []
    bounds = [0] + [i for i in starts if i > 0] + [len(lines)]
    return ["\n" * a + "".join(lines[a:b]) for a, b in zip(bounds, bounds[1:]) if b > a]


def typescript_functions(lizard, full):
    # lizard loses its place in TypeScript after some type shapes, such as an
    # object type inside a generic (Promise<{ a: string }>), and folds the
    # functions after it into one. Reading each top-level statement on its own
    # keeps a misread inside that statement.
    # As lizard reads a file: a byte that is not UTF-8 never stops the check, and a BOM is dropped.
    with open(full, encoding="utf-8-sig", errors="replace") as f:
        text = f.read()
    return [fn for chunk in top_level_chunks(text)
            for fn in lizard.analyze_file.analyze_source_code(full, chunk).function_list]


def param_count(path, f):
    # lizard's own count, the one its -a limit uses. It includes a Python
    # method's self or cls, which the caller never passes.
    names = f.parameters
    if path.endswith(".py") and names and names[0] in ("self", "cls"):
        return f.parameter_count - 1
    return f.parameter_count


class Findings:
    def __init__(self):
        self.hard, self.soft, self.unread = [], [], set()
        self.lizard_missing = False

    def judge(self, path, construct, name, value, limits):
        if not limits:
            return
        soft, hard = limits
        if value > hard:
            self.hard.append((path, construct, name, value, hard))
        elif value > soft:
            self.soft.append((path, construct, name, value, soft))


def measure_file(found, path, shared, limits):
    try:
        with open(os.path.join(ROOT, path), encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        return  # Tracked but deleted in the working tree.
    file_limits = limits["file"]
    if file_limits and is_test(path):
        file_limits = tuple(int(n * TEST_FILE_FACTOR) for n in file_limits)
    found.judge(path, "file", "-", len(lines), file_limits)
    if limits["line"]:
        # The value is how many lines run past the limit, so fixing some shows.
        soft, hard = limits["line"]
        over_hard = sum(1 for line in lines if len(line) > hard)
        over_soft = sum(1 for line in lines if len(line) > soft)
        if over_hard:
            found.hard.append((path, "line_length", "-", over_hard, hard))
        elif over_soft:
            found.soft.append((path, "line_length", "-", over_soft, soft))
    funcs = functions(path)
    if funcs is None:
        found.lizard_missing = True
        return
    if funcs is False:
        found.unread.add(os.path.splitext(path)[1])
        return
    for name, length, ccn, params in funcs:
        found.judge(path, "function", name, length, limits["function"])
        found.judge(path, "ccn", name, ccn, shared.get("ccn"))
        found.judge(path, "params", name, params, shared.get("params"))


def ledger_fields(line, reason):
    """(path, construct, name), last field. A reason may hold "|", so it takes
    the rest of the line; a baseline value is digits only, so the name takes
    everything before it, and a name holding "|" (a C++ operator|) reads back."""
    if reason:
        fields = [p.strip() for p in line.split("|", 3)]
        return (tuple(fields[:3]), fields[3]) if len(fields) == 4 else None
    head, _, value = line.rpartition("|")
    fields = [p.strip() for p in head.split("|", 2)]
    return (tuple(fields), value.strip()) if len(fields) == 3 else None


def load_ledger(path, reason=False):
    entries = {}
    if not os.path.exists(path):
        return entries
    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.strip()
            parsed = ledger_fields(line, reason) if line and not line.startswith("#") else None
            if parsed:
                # A list per key: one file can hold several same-named functions.
                entries.setdefault(parsed[0], []).append(parsed[1])
    return entries


def leftovers(hard, baseline):
    """Baseline keys that list more breaches than the tree still has: a line
    left after its code complied would excuse the next breach of that name."""
    current = {}
    for item in hard:
        current[item[:3]] = current.get(item[:3], 0) + 1
    return [(key, len(values), current.get(key, 0))
            for key, values in sorted(baseline.items()) if len(values) > current.get(key, 0)]


def write_baseline(hard):
    os.makedirs(os.path.dirname(BASELINE), exist_ok=True)
    with open(BASELINE, "w", encoding="utf-8", newline="\n") as f:
        f.write("# Hard size breaches the project had when this was written. One that is\n")
        f.write("# not listed, or whose value grew past the listed one, fails the check.\n")
        f.write("# Delete a line once its code complies. Rewrite with --write-baseline.\n")
        f.write("# path|construct|name|value\n")
        for path, construct, name, value, _ in sorted(hard):
            f.write(f"{path}|{construct}|{name}|{value}\n")
    print(f"baseline written: {len(hard)} hard breaches recorded")


def compare(hard, baseline):
    """Breaches that share a key (several `(anonymous)` callbacks in one file,
    say) pair up with the recorded ones largest to largest; any beyond the
    recorded count are new."""
    by_key = {}
    for item in hard:
        by_key.setdefault(item[:3], []).append(item)
    new, grown, tolerated = [], [], []
    for key, items in by_key.items():
        # A value that is not a number allows nothing, so its breach fails.
        recorded = sorted((int(v) if v.isdigit() else -1 for v in baseline.get(key, [])), reverse=True)
        for i, item in enumerate(sorted(items, key=lambda it: it[3], reverse=True)):
            if i >= len(recorded):
                new.append(item)
            elif item[3] > recorded[i]:
                grown.append(item + (recorded[i],))
            else:
                tolerated.append(item)
    return new, grown, tolerated


def report(found, problems, compared, verbose):
    new, grown, tolerated = compared
    failed = bool(found.lizard_missing or problems or new or grown)
    if found.lizard_missing:
        print("SIZE_CHECK_DEGRADED: lizard is not installed, so no function rows ran (pip install lizard)")
    for problem in problems:
        print(problem)
    for path, construct, name, value, limit in new:
        print(f"SIZE_BREACH_NEW: {path}: {construct} {name} = {value} (hard limit {limit}); "
              "shrink it, or record a reason in .github/size-check/exceptions.txt")
    for path, construct, name, value, limit, base in grown:
        print(f"SIZE_BREACH_GREW: {path}: {construct} {name} = {value} (baseline {base}); "
              "recorded breaches may only shrink")
    if verbose:
        for path, construct, name, value, _ in tolerated:
            print(f"baselined: {path}: {construct} {name} = {value}")
        for path, construct, name, value, limit in sorted(found.soft):
            print(f"soft: {path}: {construct} {name} = {value} (soft limit {limit})")
        for ext in sorted(found.unread):
            print(f"note: lizard reads no functions from {ext} files; only their file and line rows ran")
    if not failed:
        print(f"size check clean ({len(tolerated)} recorded breaches tolerated, {len(found.soft)} soft; see --report)")
    return 1 if failed else 0


def main(argv=None):
    ap = argparse.ArgumentParser(description="Code-size check with a ratchet")
    ap.add_argument("--write-baseline", action="store_true", help="record today's hard breaches")
    ap.add_argument("--report", action="store_true", help="also list tolerated and soft findings")
    args = ap.parse_args(argv)

    with open(RULE, encoding="utf-8") as f:
        shared, by_ext, notes = read_rule(f.read())
    for note in notes:
        print(f"note: {note}")
    if not by_ext:
        # A clean result would only mean nothing was measured.
        print("SIZE_RULE_EMPTY: .claude/rules/code-size.md gives limits for no file type")
        return 1
    files = tracked_files(by_ext)
    found = Findings()
    for path in files:
        measure_file(found, path, shared, by_ext[os.path.splitext(path)[1]])

    exceptions = load_ledger(EXCEPTIONS, reason=True)
    hard = [h for h in found.hard if h[:3] not in exceptions and (h[0], h[1], "*") not in exceptions]
    if args.write_baseline:
        if found.lizard_missing:
            print("refusing to write a baseline without lizard: "
                  "it would leave out every function row (pip install lizard)")
            return 1
        write_baseline(hard)
        return 0

    baseline = load_ledger(BASELINE)
    tracked = set(files)
    problems = [f"SIZE_LEDGER_STALE: {'|'.join(k)} names a file that is no longer tracked"
                for k in list(exceptions) + list(baseline) if k[0] not in tracked]
    problems += [f"SIZE_LEDGER_LEFTOVER: {'|'.join(key)} is listed {listed} times in the baseline but breaches "
                 f"{now} times; delete the lines whose code now complies"
                 for key, listed, now in leftovers(hard, baseline) if key[0] in tracked]
    return report(found, problems, compare(hard, baseline), args.report)


if __name__ == "__main__":
    sys.exit(main())

